package data_structures.graphs;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Graph {
public record GraphEdge<V>(V from,V to,double weight){}public record MatrixResult<V>(List<V> vertices,double[][] matrix){}public record ListResult<V>(List<V> vertices,List<List<Integer>> list){}public static class GraphImpl<V>{public final boolean directed;private final Map<V,Map<V,Double>> adjacency=new LinkedHashMap<>();public GraphImpl(){this(false);}public GraphImpl(boolean d){directed=d;}public int vertexCount(){return adjacency.size();}public int edgeCount(){return edges().size();}public GraphImpl<V> addVertex(V v){adjacency.computeIfAbsent(v,k->new LinkedHashMap<>());return this;}public GraphImpl<V> addEdge(V a,V b){return addEdge(a,b,1);}public GraphImpl<V> addEdge(V a,V b,double w){addVertex(a).addVertex(b);adjacency.get(a).put(b,w);if(!directed)adjacency.get(b).put(a,w);return this;}public boolean removeEdge(V a,V b){if(!hasEdge(a,b))return false;adjacency.get(a).remove(b);if(!directed)adjacency.get(b).remove(a);return true;}public boolean removeVertex(V v){if(!adjacency.containsKey(v))return false;adjacency.remove(v);for(var n:adjacency.values())n.remove(v);return true;}public boolean hasVertex(V v){return adjacency.containsKey(v);}public boolean hasEdge(V a,V b){return adjacency.containsKey(a)&&adjacency.get(a).containsKey(b);}public Double weight(V a,V b){return adjacency.containsKey(a)?adjacency.get(a).get(b):null;}public List<V> neighbors(V v){return adjacency.containsKey(v)?new ArrayList<>(adjacency.get(v).keySet()):new ArrayList<>();}public int degree(V v){return neighbors(v).size();}public List<V> vertices(){return new ArrayList<>(adjacency.keySet());}public List<GraphEdge<V>> edges(){List<GraphEdge<V>> o=new ArrayList<>();Set<V> seen=new HashSet<>();for(var a:adjacency.entrySet()){for(var b:a.getValue().entrySet())if(directed||!seen.contains(b.getKey()))o.add(new GraphEdge<>(a.getKey(),b.getKey(),b.getValue()));seen.add(a.getKey());}return o;}public MatrixResult<V> toAdjacencyMatrix(){List<V> v=vertices();Map<V,Integer> idx=new HashMap<>();for(int i=0;i<v.size();i++)idx.put(v.get(i),i);double[][] m=new double[v.size()][v.size()];for(var a:adjacency.entrySet())for(var b:a.getValue().entrySet())m[idx.get(a.getKey())][idx.get(b.getKey())]=b.getValue();return new MatrixResult<>(v,m);}public ListResult<V> toAdjacencyList(){List<V> v=vertices();Map<V,Integer> idx=new HashMap<>();for(int i=0;i<v.size();i++)idx.put(v.get(i),i);List<List<Integer>> o=new ArrayList<>();for(V x:v){List<Integer> n=new ArrayList<>();for(V y:neighbors(x))n.add(idx.get(y));o.add(n);}return new ListResult<>(v,o);}}
}
